import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.CPZ999nZ.js";const g=JSON.parse('{"title":"Releasing ADP","description":"","frontmatter":{},"headers":[],"relativePath":"agent-data-plane/releasing.md","filePath":"agent-data-plane/releasing.md","lastUpdated":1795784283000}'),n={name:"agent-data-plane/releasing.md"};function o(l,e,r,h,d,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="releasing-adp" tabindex="-1">Releasing ADP <a class="header-anchor" href="#releasing-adp" aria-label="Permalink to &quot;Releasing ADP&quot;">​</a></h1><p>This page covers the overall release process for Agent Data Plane, including the steps required to create a new release, as well as the technical details around how we determine the version of the release, what metadata is collected/generated, and more.</p><h2 id="high-level-overview" tabindex="-1">High-level overview <a class="header-anchor" href="#high-level-overview" aria-label="Permalink to &quot;High-level overview&quot;">​</a></h2><p>Each ADP minor version is a <strong>release line</strong>, developed on a <code>releases/X.Y.x</code> branch. A release line supports one Datadog Agent minor, its <strong>target</strong>, for its whole life. The release process roughly looks like this:</p><ul><li>for a new release line, cut <code>releases/X.Y.x</code> from <code>main</code></li><li>open a PR into the release branch to select the correct Agent version in <code>.datadog-agent-version.json</code></li><li>create a GitHub release, which tags the release branch at a particular point</li><li>creation of the Git tag triggers a CI pipeline that checks the tag and additionally unlocks jobs to publish release artifacts</li><li>the additional CI jobs, once manually triggered, will publish ADP container images to various public container image registries</li><li>bump the version of ADP to the next development version</li><li>post a release announcement in the <code>#agent-data-plane</code> Slack channel</li></ul><h2 id="release-lines-and-their-target" tabindex="-1">Release lines and their target <a class="header-anchor" href="#release-lines-and-their-target" aria-label="Permalink to &quot;Release lines and their target&quot;">​</a></h2><p><code>.datadog-agent-release-lines.jsonl</code> maps each ADP line to its target, one entry per line:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;agent_data_plane&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.9&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;agent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;7.87&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;agent_data_plane&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.10&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;agent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;7.88&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The checks require each line in exactly this form, sorted by ADP line. <code>main</code> must have an entry for the ADP version in <code>bin/agent-data-plane/Cargo.toml</code>. When <strong>Bump ADP Version</strong> moves <code>main</code> to a new minor, it appends that line&#39;s entry with the newest Agent minor plus one. Edit the entry in that pull request if the line targets another Agent, such as a new major.</p><p>The release branch&#39;s <code>.datadog-agent-version.json</code> holds the target, as <code>&quot;target&quot;: &quot;7.87&quot;</code>, and it must match the line&#39;s entry. <code>main</code> has no target. The Linux ADP build on a release branch compiles with the target&#39;s patch zero, such as <code>DD_AGENT_VERSION=7.87.0</code>, so version gates select the target&#39;s behavior even when CI tests a later RC or patch. <a href="./../development/agent-version#what-target-changes">Datadog Agent version</a> lists everything else the target changes.</p><p>The target is set once, by the release-cut commit. After the cut, no pull request may add, remove, or change it. Adding it is allowed only when the release branch doesn&#39;t have it yet: at the cut, or in a reviewed migration of an older line.</p><h2 id="release-line-lifecycle" tabindex="-1">Release line lifecycle <a class="header-anchor" href="#release-line-lifecycle" aria-label="Permalink to &quot;Release line lifecycle&quot;">​</a></h2><ol><li>ADP <code>main</code> is at 1.9.0, tests Agent 7.87 nightlies, and <code>.datadog-agent-release-lines.jsonl</code> maps 1.9 to 7.87.</li><li>Cut <code>releases/1.9.x</code> from <code>main</code>, before the Agent cuts its 7.87 release branch.</li><li>Tag 1.9.0 on <code>releases/1.9.x</code> and publish. Bump ADP Version moves <code>releases/1.9.x</code> to 1.9.1, and moves <code>main</code> to 1.10.0 with a new 1.10 → 7.88 entry for the next cut.</li><li>A PR in datadog-agent adopts ADP 1.9.0 when its release artifacts are available.</li><li>The Agent cuts 7.87.x with ADP 1.9. Agent <code>main</code> moves to 7.88, and ADP <code>main</code> follows its nightlies.</li><li>Update Agent Release Version moves <code>releases/1.9.x</code> through 7.87 RCs, then stable releases. Fixes ship as 1.9.x patches.</li><li>To stop supporting 1.9, remove <code>1.9.x</code> from <code>MAINTAINED_LINES</code> in <code>.github/workflows/update-agent-version.yml</code>.</li></ol><h2 id="cutting-a-new-release-line" tabindex="-1">Cutting a new release line <a class="header-anchor" href="#cutting-a-new-release-line" aria-label="Permalink to &quot;Cutting a new release line&quot;">​</a></h2><p>Use this order. The target must exist in the commit you tag, so the branch comes first. The examples cut ADP 1.9 for Agent 7.87.</p><p>Cut the line before the Agent cuts its release branch for the target minor, so that branch starts with this ADP line. Until the next cut, Agent <code>main</code> uses this line, one minor behind its own version. The rule of one Agent minor per ADP line applies to Agent release branches, RCs and stable releases.</p><ol><li><p>Find the target in <code>.datadog-agent-release-lines.jsonl</code> on <code>main</code>, from the entry for the ADP version in <code>bin/agent-data-plane/Cargo.toml</code>: ADP 1.9.0 needs target 7.87.</p></li><li><p>Create <code>releases/1.9.x</code> from the chosen <code>main</code> commit. The branch inherits <code>main</code>&#39;s release-lines file and its <code>.datadog-agent-version.json</code>, which holds a nightly and no target.</p></li><li><p>Open a pull request into <code>releases/1.9.x</code> that selects the line&#39;s Agent. This is the release-cut commit. It adds <code>&quot;target&quot;: &quot;7.87&quot;</code> to <code>.datadog-agent-version.json</code>, and it sets the Integration version to an Agent build from 7.87:</p><ul><li><p>If 7.87 has a complete RC, let the discovery tool write the whole file. It reads the Agent&#39;s 7.87 tags from GitHub, resolves the newest complete RC&#39;s images to digests, downloads and hashes its packages, and writes a file that includes the target. On the branch, run:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci/tooling/update-agent-version/discover_agent_version.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7.87</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --base-branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> releases/1.9.x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/release-cut</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/release-cut/datadog-agent-version.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .datadog-agent-version.json</span></span></code></pre></div><p>If no RC is complete, it writes only <code>/tmp/release-cut/summary.json</code>, which says why.</p></li><li><p>If 7.87 has no complete RC, see <a href="#before-the-target-minor-has-an-rc">Before the target minor has an RC</a>.</p></li></ul><p>Run <code>make check-agent-version</code> before you push. It fails when the Integration version is outside the target.</p></li><li><p>Wait for the pull request&#39;s CI to pass, then merge it. Check the target, the Integration version, and the ADP crate version.</p></li><li><p>Tag <code>1.9.0</code> on the release branch (see <a href="#quick-steps">Quick steps</a>), publish from the tag, and let the <strong>Bump ADP Version</strong> workflow open the development-version bumps for <code>main</code> and the release branch.</p></li><li><p>Add <code>1.9.x</code> to <code>MAINTAINED_LINES</code> in <code>.github/workflows/update-agent-version.yml</code> on <code>main</code>, so the line gets newer 7.87 RCs and stable releases.</p></li></ol><h3 id="before-the-target-minor-has-an-rc" tabindex="-1">Before the target minor has an RC <a class="header-anchor" href="#before-the-target-minor-has-an-rc" aria-label="Permalink to &quot;Before the target minor has an RC&quot;">​</a></h3><p>The branch inherits <code>main</code>&#39;s nightly. If that nightly is from the target minor, such as <code>7.87.0-devel+git.394.462b537.pipeline.151347634</code> for target 7.87, keep it and add only the <code>target</code> field by hand:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schema_version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;7.87&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;integration&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nightly&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;7.87.0-devel+git.394.462b537.pipeline.151347634&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>If Agent <code>main</code> has already moved to the next minor, the inherited nightly is outside the target. Take the last nightly from the target minor out of <code>main</code>&#39;s history of the file, then add <code>target</code>:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin/main</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .datadog-agent-version.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">commi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:.datadog-agent-version.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .datadog-agent-version.json</span></span></code></pre></div><p>If <code>main</code> never had a nightly from the target minor, wait for a complete RC, or wait to cut. Agent release-branch nightlies don&#39;t publish the packages the file needs. Don&#39;t borrow an RC from another minor, and don&#39;t change the target to fit the available artifacts.</p><h2 id="patch-releases" tabindex="-1">Patch releases <a class="header-anchor" href="#patch-releases" aria-label="Permalink to &quot;Patch releases&quot;">​</a></h2><p>Tag <code>X.Y.Z</code> on <code>releases/X.Y.x</code>. The release checks are the same as for a new line, and the <strong>Bump ADP Version</strong> workflow bumps the release branch to the next patch development version.</p><h2 id="agent-updates-within-a-release-line" tabindex="-1">Agent updates within a release line <a class="header-anchor" href="#agent-updates-within-a-release-line" aria-label="Permalink to &quot;Agent updates within a release line&quot;">​</a></h2><p>The <strong>Update Agent Release Version</strong> workflow proposes newer Agent releases for each maintained line that has adopted <code>.datadog-agent-version.json</code>. It changes only the file&#39;s <code>integration</code>, never <code>target</code>, version gates, or code, and the branch&#39;s CI tests the new Agent. It:</p><ul><li>accepts only exact <code>X.Y.Z</code> and <code>X.Y.Z-rc.N</code> Agent tags within the target minor</li><li>lets the first complete RC replace the inherited nightly</li><li>moves through RCs, then the stable release, then stable patches, and never backwards</li><li>stays on stable patches once the line reaches stable, without proposing patch RCs</li><li>keeps the newest complete version when a newer one is missing artifacts</li></ul><p>The workflow skips maintained lines that haven&#39;t adopted the file. Those lines still count when you decide whether a version gate can be removed.</p><h2 id="release-checks" tabindex="-1">Release checks <a class="header-anchor" href="#release-checks" aria-label="Permalink to &quot;Release checks&quot;">​</a></h2><p>These checks guard a release. A tag-triggered workflow can&#39;t undo a tag, so branch CI and this page&#39;s steps prevent a bad tag, and the GitLab check prevents a bad tag from shipping:</p><ul><li>the <strong>Agent version</strong> pull request check keeps each release branch&#39;s file valid and its target unchanged</li><li>the <strong>Bump ADP Version</strong> workflow checks that an <code>X.Y.0</code> tag is on <code>releases/X.Y.x</code> and declares its line&#39;s target, before it opens the version bumps and creates the backport label</li><li>the <code>check-release-agent-version</code> job in the tag pipeline checks that the tag is on its release branch, that the ADP version matches the tag, and that the file declares its line&#39;s target with an Integration version inside it. Every publish job depends on it.</li><li>the <strong>Release notes</strong> workflow checks that an <code>X.Y.0</code> tag is on its release branch before it renders the notes</li></ul><h2 id="release-notes-for-a-new-line" tabindex="-1">Release notes for a new line <a class="header-anchor" href="#release-notes-for-a-new-line" aria-label="Permalink to &quot;Release notes for a new line&quot;">​</a></h2><p>Reno, the release-note tool, decides which release a note belongs to by walking back through the Git history of the tag being released. A note belongs to the first release tag after the commit that added it. Notes added before an earlier release tag in that history belong to that earlier release, so Reno leaves them out.</p><p>Each line is cut to <code>releases/X.Y.x</code> before its first tag, and tagged there, so no <code>X.Y.0</code> tag is in <code>main</code>&#39;s history. In this example, <code>T1</code> and <code>T2</code> are the release-cut commits:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main:              A --- B --- C --- D</span></span>
<span class="line"><span>                          \\           \\</span></span>
<span class="line"><span>releases/1.9.x:            T1 (1.9.0)  \\</span></span>
<span class="line"><span>releases/1.10.x:                        T2 (1.10.0)</span></span></code></pre></div><p>The notes added in <code>A</code> and <code>B</code> shipped in <code>1.9.0</code>. When Reno walks back from <code>1.10.0</code>, through <code>T2</code>, <code>D</code>, <code>C</code>, <code>B</code> and <code>A</code>, it never meets the <code>1.9.0</code> tag, so on its own it would list those notes again under <code>1.10.0</code>.</p><p><code>ci/tooling/release_notes.py render</code> corrects for that. When the newest earlier release, <code>1.9.0</code>, isn&#39;t in the tag&#39;s history, it takes the notes present both at <code>B</code>, where the two histories meet, and at <code>1.9.0</code>, and drops the ones Reno already gives to a release in the tag&#39;s history. It passes the rest to Reno as <code>ignore_notes</code>, in a temporary copy of the configuration; <code>releasenotes/config.yaml</code> doesn&#39;t change. Patch releases, and older lines that were tagged on <code>main</code>, have their newest earlier release in their history and render as before. A change merged to <code>main</code> after the cut and backported to <code>1.9.x</code> isn&#39;t in <code>B</code>, so its note appears in both <code>1.9.x</code> and <code>1.10.0</code>. A note removed from <code>releases/1.9.x</code> before <code>1.9.0</code> isn&#39;t in <code>1.9.0</code>, so it appears in <code>1.10.0</code>.</p><h2 id="older-release-lines" tabindex="-1">Older release lines <a class="header-anchor" href="#older-release-lines" aria-label="Permalink to &quot;Older release lines&quot;">​</a></h2><p>Release lines cut before <code>.datadog-agent-version.json</code> existed keep their existing process until someone migrates them: their checks skip lines without the file, and published tags are never rewritten. Migrating a line means auditing its intended Agent minor and its version gates, then adding its release-lines entry and the file with its <code>target</code> in reviewed pull requests. Once a line has the file, removing the file or <code>target</code> doesn&#39;t exempt it from the checks.</p><h2 id="quick-steps" tabindex="-1">Quick steps <a class="header-anchor" href="#quick-steps" aria-label="Permalink to &quot;Quick steps&quot;">​</a></h2><ul><li>Ensure that the release branch is up-to-date with all of the intended changes that should be present, and that CI tests are passing cleanly (this will get checked in the actual release CI pipeline, but easier to catch problems early). For a new release line, cut the branch and commit its target first (see <a href="#cutting-a-new-release-line">Cutting a new release line</a>).</li><li>Go to the <a href="https://github.com/DataDog/saluki/releases" target="_blank" rel="noreferrer">Releases</a> page on GitHub and click the <code>Draft a new release</code> button.</li><li>Fill in the appropriate Git tag (see <a href="#determining-the-version">&quot;Determining the version&quot;</a> below), set the target to the <code>releases/X.Y.x</code> branch, and click <code>Create new tag ... on publish</code>.</li><li>Leave <code>Previous tag</code> at <code>auto</code>, and change <code>Release title</code> to <code>Agent Data Plane &lt;version&gt;</code>, where <code>&lt;version&gt;</code> is the Git tag being created. (for example, <code>Agent Data Plane 0.2.0</code>)</li><li>Click the <code>Generate release notes</code> to automatically populate the relevant changes since the last release.</li><li>If there are any additional notes that should be included, add a new section, called <code>Additional Notes</code>, at the top of the release notes. (above the auto-generated <code>What&#39;s Changed</code> section)</li><li>Click <code>Publish release</code>.</li><li>Confirm that the GitHub <code>Release notes</code> workflow for the tag succeeds. It adds curated release notes above GitHub&#39;s generated <code>What&#39;s Changed</code> pull request list. Do this before publishing release artifacts or announcing the release. The workflow cannot repair releases whose tags predate <code>releasenotes/config.yaml</code>; these releases do not receive curated notes for prior releases.</li><li>Go to the <a href="https://gitlab.ddbuild.io/DataDog/saluki/-/pipelines" target="_blank" rel="noreferrer">GitLab CI pipelines dashboard</a> for the repository and find the pipeline that was triggered for the newly created Git tag. It may take a minute or two for the repository sync and pipeline creation to occur.</li><li>The pipeline should progress through the <code>test</code>, <code>build</code>, <code>correctness</code>, and <code>release</code> stages without issue, including the <code>check-release-agent-version</code> job.</li><li>Once all stages have completed, the <code>release</code> stage will have a number of blocked jobs: standalone image publishing, release tarball publishing, and so on. These jobs perform any necessary final packaging and publish ADP release artifacts, in their various forms, to the relevant container registries and object storage. They <em>must</em> be triggered manually.</li><li>Once triggered, they should run to completion.</li><li>Once complete, you should be able to navigate to a public container image registry that we use, such as <a href="https://hub.docker.com/r/datadog/agent-data-plane/tags" target="_blank" rel="noreferrer">Docker Hub</a>, and find the resulting images: if the tag was <code>0.2.0</code>, you should be able to see a recently published image with a tag that looks like <code>0.2.0</code> and <code>0.2.0-fips</code>.</li><li>Post a release announcement in the <code>#agent-data-plane</code> Slack channel in the following format:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent Data Plane vX.Y.Z: &lt;link to GitHub release&gt;</span></span>
<span class="line"><span>CI pipeline: &lt;link to GitLab CI pipeline for the git tag&gt;</span></span></code></pre></div></li></ul><h2 id="determining-the-version" tabindex="-1">Determining the version <a class="header-anchor" href="#determining-the-version" aria-label="Permalink to &quot;Determining the version&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Git tags <strong>must</strong> be in the format of <code>X.Y.Z</code>.</p></div><p>For ADP, we use the Git tag to drive the versioning of the release artifacts themselves, but the tag is expected to match the version of the <code>agent-data-plane</code> crate. This is due to how we use the version of the <code>agent-data-plane</code> crate itself for embedding static metadata in the ADP binaries. The version of the ADP binary can be found in the <code>bin/agent-data-plane/Cargo.toml</code> file, under the <code>version</code> field.</p><h3 id="determining-the-next-version" tabindex="-1">Determining the <em>next</em> version <a class="header-anchor" href="#determining-the-next-version" aria-label="Permalink to &quot;Determining the _next_ version&quot;">​</a></h3><p>Normally, a CI job will run to bump the patch release of ADP after the Git tag is generated for the current release. In some cases, we may need to bump the minor or major version due to major/breaking changes. When deciding what minor/major version to bump to, we follow the <a href="https://semver.org/" target="_blank" rel="noreferrer">Semantic Versioning</a> specification. This means, in a nutshell:</p><ul><li>prior to v1.0.0: <ul><li>breaking changes are indicated by incrementing the minor version</li><li>new features and bug fixes are generally indicated by incrementing the patch version</li><li>if there are enough new features/bug fixes, we may instead opt to increment the minor version just for simplicity</li></ul></li><li>after v1.0.0: <ul><li>breaking changes are indicated by incrementing the major version (this should generally never happen after v1)</li><li>new features are indicated by incrementing the minor version</li><li>bug fixes are indicated by incrementing the patch version</li></ul></li></ul><h2 id="build-metadata" tabindex="-1">Build metadata <a class="header-anchor" href="#build-metadata" aria-label="Permalink to &quot;Build metadata&quot;">​</a></h2><p>We calculate a number of values that are used to populate what we call <em>build metadata</em>, which is information passed in during the build process and is used to drive a number of behaviors:</p><ul><li>outputting the version of ADP, when it was built, the build architecture, etc, as a log at startup</li><li>special constant identifiers that are used to populate things like HTTP request headers (user agent, etc)</li></ul><p>This build metadata is calculated with a Make target—<code>emit-adp-build-metadata</code>—which populates it during local builds or regular CI builds. The relevant build arguments are all prefixed with <code>APP_</code> and are as follows:</p><ul><li><code>APP_GIT_HASH</code>: the Git commit the build was performed from (set to the GitLab CI commit SHA)</li><li><code>APP_BUILD_TIME</code>: the time the build was performed (set to the creation time of the GitLab CI pipeline)</li><li><code>APP_DEV_BUILD</code>: whether this is a development build (set to <code>false</code> only for tag pipelines)</li></ul><p>Note that <code>APP_DEV_BUILD</code> also acts as a safety check: when it is <code>false</code>, <code>saluki-metadata</code>&#39;s build script fails the build if any of the values above are missing or still hold their placeholder defaults. This keeps a release binary from silently shipping metadata that reports <code>unknown</code>.</p><p>This build metadata shouldn&#39;t need to be manually changed on a per-release basis, and so this section is mostly informational and not relevant to the release process itself.</p><h2 id="software-bill-of-materials-sbom" tabindex="-1">Software bill of materials (SBOM) <a class="header-anchor" href="#software-bill-of-materials-sbom" aria-label="Permalink to &quot;Software bill of materials (SBOM)&quot;">​</a></h2><p>Every ADP binary produced in CI -- both the internal/dev images built on each pipeline and the published release artifacts -- embeds a software bill of materials (SBOM): a compact JSON record of the exact dependency tree the binary was built from. This lets you audit a shipped binary for vulnerable dependencies without access to its source tree or <code>Cargo.lock</code>.</p><p>The SBOM is produced by <a href="https://github.com/rust-secure-code/cargo-auditable" target="_blank" rel="noreferrer"><code>cargo-auditable</code></a>, used during CI to build ADP in a way that captures the exact dependencies used, both the name and version. The dependency list lives in a dedicated linker section of the binary, adds only a few kilobytes, survives stripping, and is reproducible-build-safe (no timestamps; sorted output). It is also natively supported by tools like <code>cargo-audit</code> and Trivy, making it possible for customers to audit ADP binaries for vulnerable dependencies without access to the source code or bespoke tooling.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Local developer builds (<code>make build-adp</code>, <code>make build-adp-host</code>, <code>make build-adp-image</code>) do <strong>not</strong> embed an SBOM. The wrapper is enabled only in CI, where GitLab sets <code>CI=true</code> (host builds) or the build passes <code>USE_CARGO_AUDITABLE=true</code> (Linux Docker builds). The SBOM only matters for artifacts we ship, so local builds stay on plain <code>cargo build</code>.</p></div><p>To inspect the SBOM embedded in a binary, use <code>rust-audit-info</code> or <code>cargo-audit</code>&#39;s <code>bin</code> subcommand:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Print the embedded dependency tree as JSON.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rust-audit-info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/agent-data-plane</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or scan it directly against the RustSec advisory database.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> audit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/agent-data-plane</span></span></code></pre></div><p>The <code>cargo-auditable</code> version is pinned in the <code>Makefile</code> (the <code>CARGO_TOOL_VERSION_cargo-auditable</code> variable), which the host and Linux Docker builds share. The Windows build pins the same version and its archive checksum separately in <code>ci/tooling/windows-build-adp.ps1</code>; bump both together.</p>`,62)])])}const u=a(n,[["render",o]]);export{g as __pageData,u as default};
